<script setup>
import {ref,computed,watch,onUnmounted} from 'vue';
import {Search,Music,Play,Download,LoaderCircle,AlertCircle,CheckCircle2,RefreshCw,X,FolderOpen,ListMusic,Link2} from 'lucide-vue-next';
import {size,duration} from './formatters.js';
import {activeStatus} from './selectors.js';

const props=defineProps({active:Boolean,api:Function,jobs:{type:Array,default:()=>[]},busy:Boolean,downloadDir:String});
const emit=defineEmits(['download','batch-download','preview','results','downloads']);
const status=ref(null),probing=ref(false),keyword=ref(''),source=ref('MiguMusicClient'),searching=ref(false),searched=ref(false),tracks=ref([]),results=ref([]),error=ref(''),chosen=ref([]),lastQuery=ref('');
const mode=ref('search'),playlistURL=ref(''),playlistSource=ref('MiguMusicClient'),lastMode=ref('search');
let controller=null,requestNumber=0;
const sources=computed(()=>status.value?.sources||[]);
const availableSources=computed(()=>mode.value==='playlist'?sources.value.filter(s=>s.playlist):sources.value);
const currentSource=computed({get:()=>mode.value==='playlist'?playlistSource.value:source.value,set:value=>{if(mode.value==='playlist')playlistSource.value=value;else source.value=value}});
const selectedSources=computed(()=>mode.value==='playlist'?[playlistSource.value]:source.value==='common'?['MiguMusicClient','NeteaseMusicClient','QQMusicClient','KuwoMusicClient']: [source.value]);
const playlistValid=computed(()=>{try{const url=new URL(playlistURL.value.trim());return ['http:','https:'].includes(url.protocol)&&!!url.hostname&&!url.username&&!url.password}catch{return false}});
const canSubmit=computed(()=>status.value?.ready&&!searching.value&&(mode.value==='playlist'?playlistValid.value&&!!playlistSource.value:!!keyword.value.trim()));
const allSelected=computed(()=>tracks.value.length>0&&chosen.value.length===tracks.value.length);
const downloaded=computed(()=>new Set(props.jobs.filter(j=>j.status==='completed').map(j=>j.resourceId)));
const queued=computed(()=>new Set(props.jobs.filter(j=>activeStatus(j.status)||j.status==='paused').map(j=>j.resourceId)));

async function probe(){
 if(probing.value)return;probing.value=true;error.value='';
 try{status.value=await props.api('music/status');if(status.value.ready&&!sources.value.some(s=>s.id===source.value)&&source.value!=='common')source.value=sources.value[0]?.id||'';if(!sources.value.some(s=>s.id===playlistSource.value&&s.playlist))playlistSource.value=sources.value.find(s=>s.playlist)?.id||''}
 catch(e){error.value=e.message}finally{probing.value=false}
}
watch(()=>props.active,active=>{if(active&&!status.value)void probe()},{immediate:true});
watch(playlistURL,value=>{
 try{const host=new URL(value.trim()).hostname.toLowerCase();const matches={'music.163.com':'NeteaseMusicClient','y.qq.com':'QQMusicClient','c.y.qq.com':'QQMusicClient','music.migu.cn':'MiguMusicClient','m.music.migu.cn':'MiguMusicClient','kuwo.cn':'KuwoMusicClient','kugou.com':'KugouMusicClient'};const id=Object.entries(matches).find(([domain])=>host===domain||host.endsWith('.'+domain))?.[1];if(id&&sources.value.some(s=>s.id===id&&s.playlist))playlistSource.value=id}catch{}
});
async function search(){
 if(!canSubmit.value)return;
 controller=new AbortController();const sequence=++requestNumber;
 lastMode.value=mode.value;lastQuery.value=mode.value==='playlist'?playlistURL.value.trim():keyword.value.trim();
 const path=mode.value==='playlist'?'music/playlist':'music/search';const body=mode.value==='playlist'?{url:lastQuery.value,sources:selectedSources.value}:{keyword:lastQuery.value,sources:selectedSources.value};
 searching.value=true;error.value='';tracks.value=[];results.value=[];chosen.value=[];searched.value=false;
 try{const data=await props.api(path,body,{signal:controller.signal});if(sequence!==requestNumber)return;tracks.value=data.tracks||[];results.value=data.results||[];searched.value=true;emit('results')}
 catch(e){if(e.name!=='AbortError'&&sequence===requestNumber)error.value=e.message}
 finally{if(sequence===requestNumber){searching.value=false;controller=null}}
}
function cancel(){++requestNumber;controller?.abort();controller=null;searching.value=false;error.value=lastMode.value==='playlist'?'歌单解析已取消，可以更换链接后重试':'搜索已取消，可以修改关键词后重新搜索'}
function toggleAll(event){chosen.value=event.target.checked?tracks.value.map(t=>t.id):[]}
onUnmounted(()=>{++requestNumber;controller?.abort()});
</script>

<template>
 <section class="music-workspace" aria-label="音乐搜索">
  <div class="music-search-panel">
   <div class="music-modes" role="group" aria-label="音乐操作"><button type="button" :class="{selected:mode==='search'}" :aria-pressed="mode==='search'" :disabled="searching" @click="mode='search';error=''"><Search :size="16"/>搜索歌曲</button><button type="button" :class="{selected:mode==='playlist'}" :aria-pressed="mode==='playlist'" :disabled="searching" @click="mode='playlist';error=''"><ListMusic :size="17"/>导入歌单</button></div>
   <form class="music-form" :class="{'is-searching':searching}" @submit.prevent="search">
    <div v-if="mode==='search'" class="music-keyword"><Search :size="19" aria-hidden="true"/><input v-model="keyword" aria-label="搜索歌曲或歌手" maxlength="120" placeholder="输入歌名、歌手，发现想听的音乐" :disabled="searching"/><button v-if="keyword&&!searching" type="button" class="icon-button" aria-label="清空音乐关键词" @click="keyword=''"><X :size="15"/></button></div>
    <div v-else class="music-keyword"><Link2 :size="19" aria-hidden="true"/><input v-model="playlistURL" aria-label="音乐歌单链接" maxlength="4096" placeholder="粘贴公开歌单链接，例如网易云、QQ 或咪咕" :disabled="searching"/><button v-if="playlistURL&&!searching" type="button" class="icon-button" aria-label="清空歌单链接" @click="playlistURL=''"><X :size="15"/></button></div>
    <select v-model="currentSource" aria-label="音乐平台" :disabled="searching||!status?.ready"><option v-if="mode==='search'" value="common">常用四个平台</option><option v-for="s in availableSources" :key="s.id" :value="s.id">{{s.label}}</option></select>
    <button class="primary music-search-button" type="submit" :disabled="!canSubmit"><LoaderCircle v-if="searching" class="spin" :size="17"/><ListMusic v-else-if="mode==='playlist'" :size="17"/><Search v-else :size="17"/>{{mode==='playlist'?(searching?'解析中…':'解析歌单'):(searching?'搜索中…':'搜索音乐')}}</button>
    <button v-if="searching" type="button" @click="cancel">取消</button>
   </form>
   <div class="music-engine-line"><span v-if="probing"><LoaderCircle class="spin" :size="14"/>正在连接音乐引擎…</span><span v-else-if="status?.ready" class="music-ready"><CheckCircle2 :size="14"/>{{sources.length}} 个音乐平台<span class="music-engine-version">musicdl {{status.version}}</span></span><span v-else><AlertCircle :size="15"/>{{status?.message||'音乐引擎尚未就绪'}}</span><button v-if="!searching" class="text-button" @click="probe" :disabled="probing" aria-label="检查音乐引擎"><RefreshCw :size="14"/>重新检查</button></div>
   <p v-if="mode==='playlist'" class="music-playlist-hint">选择链接所属平台，解析后勾选歌曲下载。每次最多展示 100 项可用音源；大歌单可能需要几分钟，可随时取消。</p>
  </div>

  <p v-if="error" class="music-error" role="alert"><AlertCircle :size="17"/>{{error}}</p>
  <div v-if="searching" class="music-empty" role="status" aria-live="polite"><LoaderCircle :size="33" class="spin"/><h2>{{lastMode==='playlist'?'正在解析歌单':'正在寻找「'+lastQuery+'」'}}</h2><p>{{lastMode==='playlist'?'正在读取歌曲列表并确认可用音源。':'正在搜索并确认可用音源，结果就绪后会显示在这里。'}}</p><small>你可以继续使用其他页面，或取消这次{{lastMode==='playlist'?'解析':'搜索'}}。</small></div>
  <template v-else-if="searched">
   <div class="music-results-heading"><div><h2>{{lastMode==='playlist'?'歌单歌曲':'搜索结果'}} <span>{{tracks.length}}</span></h2><p :title="lastQuery">{{lastMode==='playlist'?'已解析歌单':'「'+lastQuery+'」'}}<span v-for="result in results" :key="result.source"> · {{result.label}} {{result.count}} 首</span></p></div><button v-if="chosen.length" class="primary" :disabled="busy" @click="emit('batch-download',chosen.slice())"><Download :size="16"/>下载所选 {{chosen.length}} 首</button></div>
   <p v-for="result in results.filter(r=>r.note)" :key="result.source" class="music-source-note"><AlertCircle :size="14"/>{{result.label}}：{{result.note}}</p>
   <div v-if="tracks.length" class="music-table-scroll"><table class="music-table"><thead><tr><th class="music-select"><input type="checkbox" aria-label="选择全部音乐" :checked="allSelected" @change="toggleAll"/></th><th>歌曲 / 歌手</th><th>专辑</th><th>平台 / 格式</th><th>时长 / 大小</th><th class="music-actions-title">操作</th></tr></thead><tbody><tr v-for="track in tracks" :key="track.id"><td><input v-model="chosen" type="checkbox" :value="track.id" :aria-label="'选择 '+track.music.title"/></td><td><div class="music-track-title"><span class="music-art"><Music :size="20"/></span><div><strong :title="track.music.title">{{track.music.title}}</strong><span>{{track.author||'未知歌手'}}</span></div></div></td><td class="music-album" :title="track.music.album">{{track.music.album||'—'}}</td><td><span class="music-platform">{{track.site}}</span><small class="music-quality">{{track.quality}}<span v-if="track.bitrate"> · {{Math.round(track.bitrate)}} kbps</span></small></td><td class="music-duration"><span>{{track.duration?duration(track.duration):'—'}}</span><small>{{track.size>0?size(track.size):'下载时确认'}}</small></td><td><div class="music-row-actions"><button class="icon-button" :aria-label="'试听 '+track.music.title" :title="'试听 '+track.music.title" @click="emit('preview',track.id)"><Play :size="17"/></button><button class="compact" :aria-label="'下载 '+track.music.title" :disabled="busy||queued.has(track.id)" @click="emit('download',track.id)"><LoaderCircle v-if="queued.has(track.id)" :size="15"/><CheckCircle2 v-else-if="downloaded.has(track.id)" :size="15"/><Download v-else :size="15"/>{{queued.has(track.id)?'已加入':downloaded.has(track.id)?'已下载':'下载'}}</button></div></td></tr></tbody></table></div>
   <div v-else class="music-empty" role="status"><Music :size="36"/><h2>暂时没有可下载的结果</h2><p>{{mode==='playlist'?'请确认歌单公开可见，且已选择链接所属平台。':'试试更完整的歌名、歌手名，或换一个音乐平台。'}}</p><button @click="search" :disabled="!canSubmit"><RefreshCw :size="16"/>{{mode==='playlist'?'重新解析':'重新搜索'}}</button></div>
  </template>
  <div v-else class="music-empty music-welcome"><span class="music-welcome-icon"><Music :size="37" stroke-width="1.5"/></span><h2>{{mode==='playlist'?'喜欢的歌单，一起带走':'把喜欢的旋律，留在本机'}}</h2><p>{{mode==='playlist'?'粘贴公开歌单链接，挑选歌曲后批量保存。':'按歌名或歌手搜索，先试听，再保存。'}}</p><div class="music-features"><span>{{mode==='playlist'?'歌单批量导入':'多平台搜索'}}</span><i>·</i><span>原格式下载</span><i>·</i><span>歌词随曲保存</span></div></div>
  <footer class="music-footer"><span><FolderOpen :size="16"/><span :title="downloadDir">保存至 {{downloadDir}}</span></span><button class="text-button" @click="emit('downloads')"><Download :size="16"/>查看下载任务</button></footer>
 </section>
</template>

<style scoped>
.music-modes{display:flex;gap:6px;margin-bottom:14px}.music-modes button{border:1px solid transparent;background:transparent;box-shadow:none;color:var(--muted);padding:8px 12px;min-height:36px;font-size:13px;border-radius:10px}.music-modes button.selected{background:rgba(255,255,255,.85);border-color:var(--glass-edge);color:var(--accent)}.music-playlist-hint{color:var(--muted);font-size:12px;line-height:1.65;margin:12px 0 0}
.music-workspace{display:flex;flex-direction:column;min-height:0;flex:1;gap:14px}.music-search-panel{padding:18px;border:1px solid var(--glass-edge);border-radius:18px;background:rgba(255,255,255,.4)}.music-form{display:grid;grid-template-columns:minmax(0,1fr) 172px auto;gap:10px;align-items:center}.music-form.is-searching{grid-template-columns:minmax(0,1fr) 172px auto auto}.music-keyword{display:flex;align-items:center;gap:10px;padding:0 12px;flex:1;min-width:150px;background:rgba(255,255,255,.75);border:1px solid var(--line-strong);border-radius:14px;color:var(--muted)}.music-keyword:focus-within{outline:2px solid var(--accent);outline-offset:2px}.music-keyword input{width:100%;min-width:0;background:transparent;border:0;outline:0;box-shadow:none;padding:12px 0;font-size:14px}.music-keyword{height:46px;box-sizing:border-box;min-width:0}.music-keyword input{height:100%;box-sizing:border-box;padding:0;font:inherit;font-size:14px}.music-form select{width:100%;min-width:0;max-width:none;height:46px;min-height:46px;box-sizing:border-box;padding:0 38px 0 14px;border:1px solid var(--line-strong);border-radius:14px;background-color:rgba(255,255,255,.75);background-position:right 13px center;color:var(--text);font:inherit;font-size:14px;line-height:1.5;text-overflow:ellipsis;white-space:nowrap;box-shadow:inset 0 1px 0 rgba(255,255,255,.8);cursor:pointer;transition:border-color .16s,background-color .16s,box-shadow .16s}.music-form select:hover:not(:disabled){border-color:rgba(49,133,228,.4);background-color:rgba(255,255,255,.92)}.music-form select:focus-visible{outline:2px solid var(--accent);outline-offset:2px}.music-form select:disabled{opacity:.6;cursor:default}.music-form>button{height:46px;min-height:46px;box-sizing:border-box;white-space:nowrap;border-radius:14px;font-size:14px;padding:0 17px}.music-engine-line{display:flex;align-items:center;gap:12px;justify-content:space-between;margin-top:12px;color:var(--muted);font-size:12px}.music-engine-line>span{display:flex;align-items:center;gap:7px}.music-engine-line .music-ready{color:#23704e}.music-engine-version{color:var(--muted);border-left:1px solid var(--line);padding-left:10px;margin-left:3px}.music-error{display:flex;align-items:center;gap:9px;border:1px solid #eec9ac;background:#fff5ec;color:#88501e;padding:12px 15px;border-radius:12px;margin:0;line-height:1.5}.music-empty{flex:1;min-height:240px;display:flex;align-items:center;justify-content:center;flex-direction:column;text-align:center;color:var(--muted);gap:14px;padding:28px}.music-empty h2{color:var(--text);font-size:21px;font-weight:600;margin:0}.music-empty p{font-size:14px;line-height:1.7;margin:0}.music-empty small{font-size:12px}.music-welcome-icon{display:grid;place-items:center;width:76px;height:76px;border-radius:24px;background:rgba(255,255,255,.75);border:1px solid white;color:var(--accent);box-shadow:var(--glass-shadow);margin-bottom:6px}.music-features{display:flex;align-items:center;gap:12px;font-size:12px;margin-top:4px}.music-features i{font-style:normal;color:#97a8bc}.music-results-heading{display:flex;align-items:center;justify-content:space-between;gap:15px}.music-results-heading h2{font-size:16px;display:flex;align-items:center;gap:10px;margin:0 0 5px}.music-results-heading h2 span{font-size:12px;background:rgba(255,255,255,.7);padding:3px 8px;border-radius:12px;color:var(--accent)}.music-results-heading p{margin:0;color:var(--muted);font-size:12px;line-height:1.6}.music-source-note{display:flex;align-items:center;gap:6px;font-size:12px;color:#88501e;margin:0;line-height:1.5}.music-table-scroll{flex:1;min-height:0;overflow:auto;border:1px solid var(--glass-edge);border-radius:16px;background:rgba(255,255,255,var(--glass-content,.68))}.music-table{width:100%;border-collapse:collapse;table-layout:fixed}.music-table th{position:sticky;top:0;z-index:1;text-align:left;font-size:12px;padding:12px 10px;white-space:nowrap}.music-table th:first-child{width:35px}.music-table th:nth-child(2){width:31%}.music-table th:nth-child(3){width:17%}.music-table th:nth-child(4){width:16%}.music-table th:nth-child(5){width:13%}.music-table th:last-child{width:126px;text-align:right;padding-right:16px}.music-table td{padding:14px 10px;border-bottom:1px solid var(--line);font-size:13px}.music-table tr:last-child td{border-bottom:0}.music-table tbody tr:hover{background:rgba(255,255,255,.48)}.music-track-title{display:flex;align-items:center;gap:11px;min-width:0}.music-art{display:grid;place-items:center;width:42px;height:42px;flex-shrink:0;border-radius:12px;background:linear-gradient(145deg,#eaf2ff,#d4e8ff);color:#3987d3}.music-track-title>div{min-width:0}.music-track-title strong{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-weight:600;margin-bottom:5px}.music-track-title div>span{color:var(--muted);font-size:12px;display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.music-album{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--muted)}.music-quality,.music-duration small{display:block;color:var(--muted);font-size:11px;margin-top:5px}.music-row-actions{display:flex;align-items:center;justify-content:flex-end;gap:5px}.music-row-actions button{min-height:34px}.music-row-actions .compact{font-size:12px;white-space:nowrap;padding:6px 8px}.music-row-actions .icon-button{width:32px;padding:6px}.music-footer{display:flex;justify-content:space-between;gap:12px;margin-top:auto;font-size:12px;color:var(--muted)}.music-footer>span{display:flex;gap:8px;align-items:center;min-width:0}.music-footer>span>span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.music-footer button{white-space:nowrap;flex-shrink:0}@media(max-width:1120px){.music-form{grid-template-columns:minmax(0,1fr) 156px auto}.music-form.is-searching{grid-template-columns:minmax(0,1fr) 156px auto auto}.music-album,.music-table th:nth-child(3){display:none}.music-table th:nth-child(2){width:37%}.music-table th:nth-child(4){width:20%}.music-table th:nth-child(5){width:18%}}

</style>
